import json,subprocess,sys,time,random
def run(req):
    data=json.dumps(req).encode()
    p=subprocess.run([sys.executable,"-I","/app/submission/main.py"],input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=90)
    return json.loads(p.stdout)
random.seed(11)
for trial in range(4):
    n=12000
    states=[{"delivered":[[]],"slots":[]} for _ in range(n)]  # non-done, P1R1D1
    edges=[];seen=set()
    for i in range(n):
        seen.add((i,"x",(i+1)%n)); edges.append([i,"x",(i+1)%n])
    acts=[f"a{k}" for k in range(8)]
    while len(edges)<60000:
        s=random.randrange(n);t=random.randrange(n);a=random.choice(acts)
        if (s,a,t) in seen: continue
        seen.add((s,a,t));edges.append([s,a,t])
    fair=[{"action":acts[k],"mode":random.choice(["weak","strong"])} for k in range(8)]
    req={"op":"audit","inputs":[[[1]]],"states":states,"edges":edges,"start":0,"fairness":fair}
    r=run(req)
    if r["liveness"]:
        print("trial",trial,"prefix",len(r["liveness"]["prefix"]),"loop",len(r["liveness"]["loop"]))
    else:
        print("trial",trial,"terminates",r["terminates"])
PYEOF
